#include <Arduino.h>
#include <DHT.h>
#include <math.h>

const float threshold = 50.0f;
DHT sensor(2, DHT22);

void setup() {
  Serial.begin(9600);
  sensor.begin();
}

void loop() {
  float humidity = sensor.readHumidity();
  if (!isnan(humidity)) {
    if (humidity > threshold) {
      Serial.println("Humidity is above the threshold");
    } else {
      Serial.println("Humidity is below the threshold");
    }
  }
  delay(2000);
}
